    public MallOrder findOrder(Long orderId) {
        // Fixed BUG-006: use orElseThrow instead of direct get() to handle missing order gracefully
        return orderRepository.findById(orderId)
                .orElseThrow(() -> new NoSuchElementException("Order not found with id: " + orderId));
    }
